<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\Job;use App\Models\Quotation;use App\Services\JobQualityAnalyzer;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class CompanyJobController extends Controller{public function index(Request $request):JsonResponse{$company=$this->company($request,false);return response()->json(['data'=>$company->jobs()->latest()->get()]);}public function store(Request $request,JobQualityAnalyzer $analyzer):JsonResponse{$company=$this->company($request,true);$data=$this->validated($request);$quote=Quotation::where('company_id',$company->id)->where('reference',$data['quotation_reference'])->where('expires_at','>',now())->first();abort_unless($quote,422,'Selecciona una cotización vigente de tu empresa.');unset($data['quotation_reference']);$quality=$analyzer->analyze($data);$job=$company->jobs()->create([...$data,'quotation_id'=>$quote->id,'created_by'=>$request->user()->id,'slug'=>$this->slug($data['title']),'status'=>'draft','quality_score'=>$quality['score'],'quality_issues'=>$quality['issues']]);return response()->json(['data'=>$job,'message'=>'Borrador de vacante guardado.'],201);}public function update(Request $request,Job $job,JobQualityAnalyzer $analyzer):JsonResponse{$company=$this->company($request,true);$this->owns($company->id,$job);abort_unless(in_array($job->status,['draft','changes_requested']),422,'Esta vacante ya no puede editarse en su estado actual.');$data=$this->validated($request);$quote=Quotation::where('company_id',$company->id)->where('reference',$data['quotation_reference'])->where('expires_at','>',now())->first();abort_unless($quote,422,'Selecciona una cotización vigente de tu empresa.');unset($data['quotation_reference']);$quality=$analyzer->analyze($data);$job->update([...$data,'quotation_id'=>$quote->id,'quality_score'=>$quality['score'],'quality_issues'=>$quality['issues']]);return response()->json(['data'=>$job->fresh(),'message'=>'Borrador actualizado.']);}public function submit(Request $request,Job $job):JsonResponse{$company=$this->company($request,true);$this->owns($company->id,$job);abort_unless(in_array($job->status,['draft','changes_requested']),422);abort_if($job->quality_score<60,422,'Mejora la calidad de la vacante antes de continuar.');$job->update(['status'=>'pending_payment','submitted_at'=>now()]);return response()->json(['data'=>$job->fresh(),'message'=>'Vacante lista para completar el pago.']);}private function validated(Request $request):array{return $request->validate(['quotation_reference'=>['required','uuid'],'title'=>['required','string','max:150'],'summary'=>['required','string','max:500'],'description'=>['required','string','max:10000'],'requirements'=>['present','array','max:20'],'requirements.*'=>['string','max:300'],'benefits'=>['present','array','max:20'],'benefits.*'=>['string','max:300'],'location'=>['required','string','max:150'],'modality'=>['required',Rule::in(['Presencial','Remoto','Híbrido'])],'contract_type'=>['required',Rule::in(['Tiempo completo','Medio tiempo','Contrato','Freelance'])],'salary_min'=>['nullable','integer','min:0'],'salary_max'=>['nullable','integer','min:0'],'currency'=>['required',Rule::in(['DOP','USD'])]]);}private function company(Request $request,bool $write){abort_unless($request->user()->account_type==='company',403);$company=$request->user()->companies()->wherePivot('status','active')->first();abort_unless($company,422,'Completa primero el perfil empresarial.');$role=$company->members()->whereKey($request->user()->id)->first()?->pivot->role;if($write)abort_unless(in_array($role,['owner','admin','recruiter']),403);return $company;}private function owns(int $companyId,Job $job):void{abort_unless($job->company_id===$companyId,404);}private function slug(string $title):string{return Str::slug($title).'-'.Str::lower(Str::random(6));}}
